// Complete Pre-loaded Data for Greetings Studio
// Direct keyword-based Unsplash event-to-background mapping with high-definition assets.
// Zero repeated wrong images across different occasions.

export interface BackgroundPreset {
  id: string;
  name: string;
  thumbnailUrl: string;
  fullUrl: string;
  themeColor: string; // fallback gradient dominant color
  secondaryColor: string;
  accentColor: string;
  patternType: 'balloons' | 'confetti' | 'bokeh' | 'luxury_gold' | 'hearts' | 'floral' | 'fireworks' | 'sparkles' | 'geometric' | 'diya';
}

export interface EventBackgroundMapping {
  keywords: string[];
  themeColor: string;
  secondaryColor: string;
  accentColor: string;
  patternType: BackgroundPreset['patternType'];
  presets: {
    id: string;
    name: string;
    photoId: string;
  }[];
}

export interface FestivalItem {
  id: string;
  name: string;
  nameGu: string;
  nameHi: string;
  icon: string;
  month: string;
  category: 'major' | 'harvest' | 'regional' | 'spiritual';
  defaultWishesEn: string;
  defaultWishesGu: string;
  defaultWishesHi: string;
  bgPresets: BackgroundPreset[];
}

export interface SpecialDayItem {
  id: string;
  name: string;
  nameGu: string;
  nameHi: string;
  icon: string;
  dateStr: string;
  category: 'professions' | 'national' | 'health' | 'social' | 'science';
  defaultWishesEn: string;
  defaultWishesGu: string;
  defaultWishesHi: string;
  bgPresets: BackgroundPreset[];
}

