// --------------------------------------------------------------------------
// DYNAMIC EVENT LOOKUP & KEYWORD SEARCH HELPERS
// --------------------------------------------------------------------------
export function getPresetsForEvent(
  eventId: string,
  category: 'festivals' | 'days'
): BackgroundPreset[] {
  if (category === 'festivals') {
    const fest = FESTIVALS_LIST.find((f) => f.id === eventId);
    if (fest && fest.bgPresets.length > 0) return fest.bgPresets;
  } else {
    const day = SPECIAL_DAYS_LIST.find((d) => d.id === eventId);
    if (day && day.bgPresets.length > 0) return day.bgPresets;
  }
  return BIRTHDAY_BACKGROUNDS;
}
